// Stops the run while a setting is still a placeholder or makes no sense, then hands on what started this run:
// the new messages of the poll, or one item for the hourly timer or the manual run. Nothing is stored or sent here.
const cfg = $('Your settings').first().json;
const source = $('Poll WhatsApp group messages').isExecuted ? 'messages' : $('Run now for one group').isExecuted ? 'now' : 'schedule';
const problems = [];
const text = (name) => String(cfg[name] ?? '').trim();
const whole = (name, min, max) => {
  const value = Number(cfg[name]);
  if (!Number.isInteger(value) || value < min || value > max) problems.push(name + ' must be a whole number from ' + min + ' to ' + max);
};
const E164 = /^\+[1-9]\d{7,14}$/;
const placeholder = (value) => /^replace with\b/i.test(value);

const watched = text('watch_groups').split(',').map((entry) => entry.trim()).filter(Boolean);
if (watched.length === 0 || watched.some(placeholder)) problems.push('watch_groups is still the sample: type the name or the id (grp_...) of each group to digest, separated by commas');
if (!['owner', 'group', 'members'].includes(text('delivery'))) problems.push('delivery must be owner, group or members');
if (!E164.test(text('owner_phone'))) problems.push('owner_phone is not a real number yet (your own number, with + and the country code)');
if (text('delivery') === 'members') {
  const members = text('members_phones').split(',').map((entry) => entry.trim()).filter(Boolean);
  if (members.length === 0 || members.length > 5 || members.some((phone) => !E164.test(phone)) || new Set(members).size !== members.length) {
    problems.push('members_phones must hold 1 to 5 different numbers with + and the country code, separated by commas');
  }
}
whole('digest_hour', 0, 23);
whole('min_messages', 1, 100000);
whole('keep_days', 2, 30);
whole('max_chars_for_model', 2000, 200000);
whole('max_text_chars', 50, 2000);
whole('max_digest_chars', 300, 3000);
whole('most_active_count', 0, 5);
if (!['true', 'false'].includes(String(cfg.mention_most_active).toLowerCase())) problems.push('mention_most_active must be true or false');
try {
  new Intl.DateTimeFormat('en', { timeZone: text('expected_timezone') });
} catch (error) {
  problems.push('expected_timezone is not a time zone name (for example America/Sao_Paulo)');
}
if (source !== 'messages' && $now.zoneName !== text('expected_timezone')) {
  problems.push('this workflow runs in the time zone ' + $now.zoneName + ' but expected_timezone is ' + text('expected_timezone') + ' (set the same one in Workflow settings, Timezone)');
}
if (source === 'now' && (!text('run_now_group') || placeholder(text('run_now_group')))) problems.push('run_now_group is empty: type the name or the id of the group to digest now');
if (!text('ai_prompt')) problems.push('ai_prompt is empty');
for (const name of ['msg_title', 'msg_footer', 'msg_most_active', 'msg_omitted', 'msg_fallback', 'msg_links']) {
  if (!text(name)) problems.push(name + ' is empty');
}

if (problems.length > 0) {
  throw new Error('Not ready to digest anything: ' + problems.join('; ') + '. Fix Your settings, then the workflow runs.');
}
if (source === 'messages') return $('Poll WhatsApp group messages').all().map((item) => ({ json: { ...item.json, source } }));
return [{ json: { source } }];

// Keeps only what must be stored: a message written in one of the groups you listed, by another person or by you.
// Private chats, groups that are not on the list and messages sent by the API (this workflow's own digest included)
// are dropped. What you type yourself in the group from the phone arrives as message.sent with origin native.
const cfg = $('Your settings').first().json;
const groups = $('Read the groups of the number').all().map((item) => item.json).filter((group) => typeof group.id === 'string' && group.id.startsWith('grp_'));
const norm = (value) => String(value ?? '').normalize('NFC').replace(/\s+/g, ' ').trim().toLowerCase();
const watched = new Map();
for (const entry of String(cfg.watch_groups).split(',').map((part) => part.trim()).filter(Boolean)) {
  const hits = /^grp_[0-9a-f]{32}$/i.test(entry)
    ? groups.filter((group) => group.id.toLowerCase() === entry.toLowerCase())
    : groups.filter((group) => norm(group.name) === norm(entry));
  if (hits.length === 1) watched.set(hits[0].id, hits[0].name ?? '');
}

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const event = item.json;
  const data = event.data ?? {};
  if (!['message.received', 'message.replied', 'message.sent'].includes(event.type)) continue;
  // A message from a person is inbound and native. Yours, typed in the app, is outbound and native. Everything the API
  // sends (origin tn) is ignored: it would include the digest itself.
  if (data.origin !== 'native') continue;
  const outbound = data.direction === 'outbound';
  if (!outbound && data.direction !== 'inbound') continue;
  if (event.type === 'message.sent' && !outbound) continue;
  const groupId = data.to?.group_id;
  if (!groupId || !watched.has(groupId) || !data.id || seen.has(data.id)) continue;
  seen.add(data.id);
  out.push({
    json: {
      message_id: data.id,
      number_id: event.number_id,
      group_id: groupId,
      group_name: watched.get(groupId),
      sender_name: data.from?.name ?? (outbound ? 'Owner' : ''),
      sender_phone: String(data.from?.number ?? '').replace(/\D/g, ''),
      sent_at: data.at ?? event.created_at,
      kind: data.content_type ?? 'text',
      preview: data.preview ?? '',
      mentions: Array.isArray(data.mentions) ? data.mentions : [],
    },
  });
}
return out;

// Turns each message read in full into the row that is stored. Text is cleaned and cut, a message without text
// becomes a marker such as [image], an expired message is dropped, and when the full message could not be read
// the 50 character preview of the event is kept instead. Phone numbers never reach the table or the model:
// an @number mention becomes @FirstName, and a bare phone number becomes [number].
const cfg = $('Your settings').first().json;
const max = Number(cfg.max_text_chars);
const kept = $('Keep the group messages to store').all();
// Control characters, zero-width and bidirectional marks become spaces (written as escapes on purpose).
const clean = (value) => String(value ?? '').replace(/[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, ' ').replace(/\s+/g, ' ').trim();
const firstName = (value) => {
  const name = clean(value).split(' ')[0] ?? '';
  return /^[\d+().-]*$/.test(name) ? '' : name.slice(0, 30);
};
const LINK = /https?:\/\/[^\s<>"')\]]+/gi;
const bare = (part) =>
  part
    .replace(/\+\d[\d\s().-]{6,}\d/g, (found) => (found.replace(/\D/g, '').length >= 9 ? '[number]' : found))
    .replace(/(?<!\d)(?:\(?\d{2,3}\)?[\s.-]?\d{4,5}|\d{5})[\s.-]\d{4}(?!\d)/g, '[number]')
    .replace(/\d{8,}/g, '[number]');
const scrub = (value, names) => {
  const text = value.replace(/@(\d{7,15})(?!\d)/g, (all, digits) => '@' + (names.get(digits) || 'someone'));
  let result = '';
  let from = 0;
  for (const found of text.matchAll(LINK)) {
    result += bare(text.slice(from, found.index));
    // A link keeps its long ids, except a WhatsApp link: it carries somebody's number.
    result += /wa\.me|whatsapp\.com|phone=/i.test(found[0]) ? '[WhatsApp link]' : found[0];
    from = found.index + found[0].length;
  }
  return result + bare(text.slice(from));
};

const out = [];
$input.all().forEach((answer, index) => {
  const base = kept[index].json;
  const got = answer.json;
  const failed = got.error !== undefined || !got.id;
  if (!failed && got.content_expired === true) return;
  const kind = String((!failed && got.content_type) || base.kind || 'text');
  let body = '';
  if (failed) body = base.preview;
  else if (kind === 'text') body = got.text;
  else if (kind === 'calendar' && got.calendar && typeof got.calendar === 'object') body = [got.calendar.name, String(got.calendar.start_at ?? '').slice(0, 16).replace('T', ' ')].filter(Boolean).join(' ');
  else if (kind === 'location' && got.location && typeof got.location === 'object') body = got.location.name || '';
  else if (got[kind] && typeof got[kind] === 'object') body = got[kind].caption || got[kind].transcription?.text || '';
  const names = new Map();
  for (const person of (failed ? base.mentions : got.mentions) ?? []) {
    const name = firstName(person?.name);
    if (name) names.set(String(person.number ?? '').replace(/\D/g, ''), name);
  }
  let text = scrub(clean((kind === 'text' ? '' : '[' + kind + '] ') + clean(body)), names);
  if (text === '') return;
  const characters = Array.from(text);
  if (characters.length > max) text = characters.slice(0, max - 1).join('') + '…';
  let name = clean(base.sender_name).slice(0, 60);
  if (/^\d{6,}$/.test(name.replace(/[\s().+-]/g, ''))) name = '';
  const at = Date.parse(base.sent_at);
  const when = Number.isFinite(at) ? at : Date.now();
  out.push({
    json: {
      message_id: base.message_id,
      group_id: base.group_id,
      group_name: base.group_name,
      sender_name: name,
      sender_phone: base.sender_phone,
      text,
      kind,
      sent_at: new Date(when).toISOString(),
      sent_ts: Math.floor(when / 1000),
      text_source: failed ? 'preview' : 'full',
    },
  });
});
return out;

// Decides which groups get a digest in this run and builds what the model reads. Nothing is sent or saved here.
const cfg = $('Your settings').first().json;
const source = $('Check the settings').first().json.source;
const timeZone = String(cfg.expected_timezone).trim();
const now = Date.now();
const localParts = (ms) => {
  const out = {};
  const format = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  for (const part of format.formatToParts(new Date(ms))) out[part.type] = part.value;
  if (out.length === 0 && missingText) throw new Error(missingText);
return out;
};
const local = localParts(now);
const today = local.year + '-' + local.month + '-' + local.day;
// The hourly timer only works from digest_hour to the end of the day: a run that was missed is caught up, once.
if (source === 'schedule' && Number(local.hour) < Number(cfg.digest_hour)) return [];

const groups = $('Read the groups of the number').all().map((item) => item.json).filter((group) => typeof group.id === 'string' && group.id.startsWith('grp_'));
const norm = (value) => String(value ?? '').normalize('NFC').replace(/\s+/g, ' ').trim().toLowerCase();
const wanted = source === 'now' ? [String(cfg.run_now_group).trim()] : String(cfg.watch_groups).split(',').map((part) => part.trim()).filter(Boolean);
const chosen = new Map();
const missing = [];
for (const entry of wanted) {
  const hits = /^grp_[0-9a-f]{32}$/i.test(entry)
    ? groups.filter((group) => group.id.toLowerCase() === entry.toLowerCase())
    : groups.filter((group) => norm(group.name) === norm(entry));
  if (hits.length === 0) missing.push('"' + entry + '" matches no group of this number');
  else if (hits.length > 1) missing.push('"' + entry + '" matches ' + hits.length + ' groups, use the id (grp_...) of the one you mean');
  else chosen.set(hits[0].id, hits[0]);
}
// One entry that cannot be found does not stop the others: the groups found get their digest, and the run then fails
// (in "Report what failed") so that the entry is fixed. A run with nothing to build fails here.
let missingText = '';
if (missing.length > 0) {
  const known = groups.slice(0, 15).map((group) => (group.name || '(no name)') + ' = ' + group.id).join(', ');
  missingText = 'Cannot find the group: ' + missing.join('; ') + '. The number is in: ' + (known || 'no group') + '. Fix watch_groups or run_now_group in Your settings, and use the id (grp_...) of each group: a name can change, the id never does.';
  if (chosen.size === 0 || source === 'now') throw new Error(missingText);
}

const stored = $('Read the stored messages').all().map((item) => item.json).filter((row) => row.message_id);
const finished = new Map($input.all().map((item) => item.json).filter((row) => row.digest_key).map((row) => [row.digest_key, row.status]));
const since = Math.floor(now / 1000) - 86400;
const firstName = (name) => String(name ?? '').trim().split(/\s+/)[0] || '';
const stamp = (seconds) => {
  const at = localParts(seconds * 1000);
  return at.month + '-' + at.day + ' ' + at.hour + ':' + at.minute;
};
const LINK = /https?:\/\/[^\s<>"')\]]+/gi;

const out = [];
for (const group of chosen.values()) {
  const key = group.id + '|' + today + (source === 'now' ? '|manual' : '');
  if (source === 'schedule' && ['delivered', 'failed_plan'].includes(finished.get(key))) continue;
  const mine = stored
    .filter((row) => row.group_id === group.id && Number(row.sent_ts) >= since)
    .sort((a, b) => Number(a.sent_ts) - Number(b.sent_ts) || (a.message_id < b.message_id ? -1 : 1));
  // A message that is only a marker ([image], [audio]) is no reason to build a digest.
  const worded = mine.filter((row) => !/^\[[a-z_]+\]$/i.test(String(row.text).trim()));
  if (source === 'schedule' && worded.length < Number(cfg.min_messages)) continue;
  if (mine.length === 0) {
    throw new Error('No stored message of "' + (group.name || group.id) + '" in the last 24 hours. The workflow stores messages only while it is active, so wait until the group writes, or check watch_groups.');
  }

  // Who wrote, how much, and the links that were shared.
  const people = new Map();
  const links = [];
  for (const row of mine) {
    const id = row.sender_phone || 'name:' + row.sender_name;
    if (!people.has(id)) people.set(id, { phone: row.sender_phone || '', full: String(row.sender_name ?? '').trim(), count: 0 });
    people.get(id).count += 1;
    for (const found of String(row.text).match(LINK) ?? []) {
      const link = found.replace(/[.,;:!?]+$/, '');
      if (!links.includes(link)) links.push(link);
    }
  }
  // The model and the readers see first names. Two people with the same first name are told apart ("Maria S.", then
  // "Maria 2"), and a sender without a name is Member 1, Member 2, ...
  const firstOf = new Map([...people].map(([id, person]) => [id, firstName(person.full)]));
  const sameFirst = new Map();
  for (const first of firstOf.values()) if (first) sameFirst.set(first.toLowerCase(), (sameFirst.get(first.toLowerCase()) ?? 0) + 1);
  const taken = new Set();
  const names = new Map();
  [...people].forEach(([id, person], position) => {
    const first = firstOf.get(id);
    const initial = (person.full.split(/\s+/)[1] ?? '').charAt(0).toUpperCase();
    const stem = first || 'Member';
    let name = first ? (sameFirst.get(first.toLowerCase()) > 1 && /\p{L}/u.test(initial) ? first + ' ' + initial + '.' : first) : 'Member ' + (position + 1);
    for (let n = 2; taken.has(name.toLowerCase()); n += 1) name = stem + ' ' + n;
    taken.add(name.toLowerCase());
    names.set(id, name);
  });
  const label = (row) => names.get(row.sender_phone || 'name:' + row.sender_name);
  const top = [...people].map(([id, person]) => ({ phone: person.phone, name: names.get(id), count: person.count })).sort((a, b) => b.count - a.count).slice(0, 5);

  // The newest messages are kept when the day does not fit in max_chars_for_model.
  const lines = mine.map((row) => '[' + stamp(Number(row.sent_ts)) + '] ' + label(row) + ': ' + row.text);
  const budget = Number(cfg.max_chars_for_model);
  let used = 0;
  let first = lines.length;
  while (first > 0 && (used + lines[first - 1].length + 1 <= budget || first === lines.length)) {
    first -= 1;
    used += lines[first].length + 1;
  }
  const kept = lines.slice(first);
  const omitted = first;
  const header = 'Group: ' + (group.name || 'a WhatsApp group') + '\nTimes are in ' + timeZone + '.\n' + (omitted > 0 ? 'The ' + omitted + ' oldest messages of the day are not included.\n' : '') + '\nMessages, oldest first:\n';
  out.push({
    json: {
      source,
      group_id: group.id,
      group_name: group.name ?? '',
      digest_key: key,
      date: today,
      count: mine.length,
      kept: kept.length,
      omitted,
      people: people.size,
      top,
      links: links.slice(0, 300),
      phones: [...people.values()].map((person) => person.phone).filter(Boolean),
      missing_text: missingText,
      newest_message_id: mine[mine.length - 1].message_id,
      system: String(cfg.ai_prompt).replace(/\{max_chars\}/g, String(cfg.max_digest_chars)),
      prompt: header + kept.join('\n'),
    },
  });
}
if (out.length === 0 && missingText) throw new Error(missingText);
return out;

// Checks what the model wrote and builds the messages that go out. A summary that is empty, that carries a phone
// number, an e-mail address or a mention token, or an answer that never came, is replaced by a plain digest made
// from the numbers (messages, most active people, links). Nothing is sent or saved here.
const cfg = $('Your settings').first().json;
const plan = $('Plan the digests');
const fill = (template, values) => String(template).replace(/\\n/g, '\n').replace(/\{(\w+)\}/g, (all, key) => (key in values ? String(values[key]) : all)).trim();
// Control characters other than line breaks, zero-width and bidirectional marks are removed (written as escapes).
const strip = (value) => String(value ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, '').replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();
const owner = String(cfg.owner_phone).trim();
const members = String(cfg.members_phones ?? '').split(',').map((part) => part.trim()).filter(Boolean);
const max = Number(cfg.max_digest_chars);
const topCount = Number(cfg.most_active_count);
const mentionTop = String(cfg.mention_most_active).toLowerCase() === 'true';

const linksOf = (value) => (String(value).match(/https?:\/\/[^\s<>"')\]]+/gi) ?? []).map((link) => link.replace(/[.,;:!?]+$/, ''));
const PHONE_LINK = /wa\.me|whatsapp\.com|phone=/i;
const problemOf = (summary, phones, shared) => {
  if (summary.length < 40) return 'empty';
  // Links are set aside (a long id inside a link is normal), except the ones that carry a phone number (wa.me).
  // Dates and times are set aside too. What is left is a phone number when it is written like one (+55 11 9XXXX-XXXX,
  // (11) 9XXXX XXXX, 9XXXX-XXXX) or when it is a run of 10 digits or more. Small numbers with spaces ("rooms 10 20 30")
  // are not phone numbers.
  const rest = summary.replace(/https?:\/\/\S+/gi, (link) => (PHONE_LINK.test(link) ? link : '#')).replace(/\d{4}-\d{2}-\d{2}/g, '#').replace(/\d{1,2}[/.-]\d{1,2}[/.-]\d{2,4}/g, '#').replace(/\d{1,2}:\d{2}/g, '#');
  const runs = [];
  let written = false;
  for (const found of rest.matchAll(/\+\d[\d\s().-]{6,}\d/g)) if (found[0].replace(/\D/g, '').length >= 9) written = true;
  for (const found of rest.matchAll(/(?<!\d)(?:\(?\d{2,3}\)?[\s.-]?\d{4,5}|\d{5})[\s.-]\d{4}(?!\d)/g)) {
    written = true;
    runs.push(found[0].replace(/\D/g, ''));
  }
  for (const found of rest.matchAll(/\d{7,}/g)) runs.push(found[0]);
  if (written || runs.some((run) => run.length >= 10) || runs.some((run) => phones.some((phone) => phone.length >= 7 && run.includes(phone.slice(-8))))) return 'phone number';
  if (/[^\s@]+@[^\s@]+\.[^\s@]+/.test(summary)) return 'e-mail address';
  if (/@\d{5,}/.test(summary)) return 'mention token';
  // A link is only repeated, never made up: every link of the summary was written in the group.
  if (linksOf(summary).some((link) => !shared.includes(link))) return 'a link that was not shared in the group';
  return '';
};

const out = [];
$input.all().forEach((answer, index) => {
  const p = plan.itemMatching(index).json;
  const raw = strip(answer.json.error !== undefined ? '' : (answer.json.text ?? answer.json.response?.text ?? answer.json.output ?? ''));
  let summary = raw;
  let kind = 'ai';
  const problem = answer.json.error !== undefined ? 'the model gave no answer' : problemOf(raw, p.phones, p.links);
  if (problem) {
    kind = 'fallback: ' + problem;
    const body = [fill(cfg.msg_fallback, {})];
    if (p.links.length > 0) body.push('', fill(cfg.msg_links, {}), ...p.links.slice(0, 10).map((link) => '- ' + link));
    summary = body.join('\n');
  } else if (summary.length > max) {
    const head = summary.slice(0, max);
    const cut = head.lastIndexOf('\n');
    summary = (cut > max / 2 ? head.slice(0, cut) : head.slice(0, head.lastIndexOf(' ') > 0 ? head.lastIndexOf(' ') : max)).trimEnd() + '…';
    kind = 'ai (cut to max_digest_chars)';
  }

  const targets =
    p.source === 'now'
      ? [{ to: owner, type: 'phone', slot: 'owner' }]
      : cfg.delivery === 'group'
        ? [{ to: p.group_id, type: 'group', slot: 'group' }]
        : cfg.delivery === 'members'
          ? members.map((phone, i) => ({ to: phone, type: 'phone', slot: 'm' + (i + 1) }))
          : [{ to: owner, type: 'phone', slot: 'owner' }];
  const named = p.top.slice(0, topCount);
  // In a private message the most active people come with their counts. In a group post they are named without counts,
  // and tagged as real @mentions only when mention_most_active is on (their phones ring).
  const active = (inGroup) => {
    if (named.length === 0) return '';
    const names = inGroup
      ? named.map((person) => (mentionTop && /^\d{7,15}$/.test(person.phone) ? '@' + person.phone : person.name)).join(mentionTop ? ' ' : ', ')
      : named.map((person) => person.name + ' (' + person.count + ')').join(', ');
    return fill(cfg.msg_most_active, { names });
  };
  const key = p.group_id.replace('grp_', '');
  for (const target of targets) {
    const lines = [fill(cfg.msg_title, { group: p.group_name || 'WhatsApp group', messages: p.count, people: p.people }), '', summary];
    const line = active(target.type === 'group');
    if (line) lines.push('', line);
    if (p.omitted > 0) lines.push('', fill(cfg.msg_omitted, { kept: p.kept, total: p.count }));
    lines.push('', fill(cfg.msg_footer, {}));
    out.push({
      json: {
        to: target.to,
        to_type: target.type,
        text: lines.join('\n').slice(0, 4000),
        key: p.source === 'now' ? 'digest-now-' + key + '-' + p.newest_message_id : 'digest-' + key + '-' + p.date + '-' + target.slot,
        digest_key: p.digest_key,
        group_id: p.group_id,
        group_name: p.group_name,
        date: p.date,
        source: p.source,
        delivery: p.source === 'now' ? 'owner' : String(cfg.delivery),
        count: p.count,
        summary_source: kind,
      },
    });
  }
});
return out;

// Matches each answer of Turbo Notify with the message that was planned for it and builds the row that is saved
// for each digest. A send that is refused is never silent: the row records it and the next node fails the run.
// A repeated send (the same key, another text) is answered "already used": the digest went out earlier, so it counts as sent.
const planned = $('Check the summary and write the messages');
const reasonOf = (error) => String(typeof error === 'string' ? error : (error && error.message) || JSON.stringify(error)).slice(0, 300);
const byDigest = new Map();
$input.all().forEach((answer, index) => {
  const send = planned.itemMatching(index).json;
  const failed = answer.json.error !== undefined || !answer.json.id;
  const reason = failed ? reasonOf(answer.json.error ?? 'Turbo Notify did not return a message id') : '';
  const already = failed && /idempotency/i.test(reason);
  if (!byDigest.has(send.digest_key)) byDigest.set(send.digest_key, []);
  // A refusal that repeats identically until the plan or the billing cycle changes is not tried again that day.
  const limit = failed && !already ? (/plan does not include|Business plan|feature_not_available/i.test(reason) ? 'plan' : /allowance is used up|quota_exceeded/i.test(reason) ? 'quota' : '') : '';
  byDigest.get(send.digest_key).push({ send, ok: !failed || already, message_id: failed ? '' : answer.json.id, reason: already ? '' : reason, limit });
});

const out = [];
for (const [digestKey, results] of byDigest) {
  const first = results[0].send;
  const failures = results.filter((result) => !result.ok);
  let status = 'delivered';
  if (first.source === 'now') status = failures.length === 0 ? 'manual' : 'manual_failed';
  else if (failures.length > 0) status = failures.every((result) => result.limit) ? 'failed_plan' : 'retry';
  out.push({
    json: {
      digest_key: digestKey,
      group_id: first.group_id,
      group_name: first.group_name,
      date: first.date,
      status,
      delivery: first.delivery,
      recipients: results.length,
      message_ids: results.map((result) => result.message_id).filter(Boolean).join(','),
      summary_source: first.summary_source,
      messages_count: first.count,
      created_at: new Date().toISOString(),
      last_error: failures.map((result) => result.send.to + ': ' + result.reason).join(' | '),
      failures: failures.map((result) => ({ to: result.send.to, reason: result.reason, limit: result.limit })),
    },
  });
}
return out;

// The last node of the run. A refused digest is never silent: the row already holds the reason, and this node makes
// the run fail, so that your Error workflow (or the Executions list) shows it and names the group and the recipient.
// A group of watch_groups that could not be found is reported here too, after the digests of the other groups went out.
const rows = $('Record what was sent').all().map((item) => item.json);
const lines = [];
for (const row of rows) {
  if (row.failures.length === 0) continue;
  const reasons = row.failures.map((failure) => failure.to + ': ' + failure.reason).join(' | ');
  const limits = row.failures.map((failure) => failure.limit);
  const hint = limits.includes('plan')
    ? ' Sending to a group needs the Business plan or higher: set delivery to owner or members in Your settings.'
    : limits.includes('quota')
      ? ' The allowance of your plan is used up until the billing cycle turns, so it is not tried again today.'
      : row.status === 'retry'
        ? ' It is tried again at the next hourly run today.'
        : '';
  lines.push('Digest of "' + (row.group_name || row.group_id) + '" (' + row.date + ') was not delivered to ' + reasons + '.' + hint);
}
const missing = $('Plan the digests').all().map((item) => item.json.missing_text).find(Boolean);
if (missing) lines.push(missing);
if (lines.length > 0) throw new Error(lines.join(' || '));
return $input.all();
